precision highp float;

uniform float u_time;
uniform vec3 u_color;
uniform float u_fresnelPower;
uniform float u_iridescence;
uniform float u_roughness;
uniform float u_pulseSpeed;
uniform float u_audio_bass;
uniform float u_audio_mid;
uniform float u_audio_treble;
uniform float u_audio_beat;

varying vec2 vUv;
varying vec3 vNormal;

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.67);
    return a + b * cos(6.28318 * (c * t + d));
}

void main() {
    vec3 normal = normalize(vNormal);
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    vec3 lightDir = normalize(vec3(1.0, 2.0, 1.5));
    vec3 halfVec = normalize(lightDir + viewDir);

    float NdotV = max(0.0, dot(normal, viewDir));
    float fresnel = pow(1.0 - NdotV, u_fresnelPower);

    float NdotH = max(0.0, dot(normal, halfVec));
    float shininess = mix(128.0, 8.0, u_roughness);
    float spec = pow(NdotH, shininess);

    float wavePhase = u_time * u_pulseSpeed * 0.5 + vUv.y * 6.28;
    float thinFilm = pow(1.0 - NdotV, 2.0) + sin(wavePhase) * 0.15 + u_audio_mid * 0.3;
    vec3 iridescentCol = palette(thinFilm * u_iridescence);

    float diff = max(0.0, dot(normal, lightDir) * 0.7 + 0.3);

    vec3 base = u_color * diff;
    float audioBoost = 1.0 + u_audio_beat * 0.5;
    vec3 rgb = (mix(base, iridescentCol, 0.65) + vec3(spec * 1.8) + iridescentCol * fresnel * 1.6) * audioBoost;

    gl_FragColor = vec4(rgb, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec3 u_shieldColor;
uniform float u_fresnelPower;
uniform float u_scanlineSpeed;
uniform float u_hexScale;

varying vec2 vUv;
varying vec3 vNormal;

// Hexagonal tiling pattern
float hexPattern(vec2 p) {
    p *= u_hexScale;
    vec2 q = vec2(p.x * 2.0 / sqrt(3.0), p.y + p.x / sqrt(3.0));
    vec2 pi = floor(q);
    vec2 pf = fract(q);
    float v = min(min(pf.x, 1.0 - pf.x), min(pf.y, 1.0 - pf.y));
    return smoothstep(0.0, 0.08, v);
}

void main() {
    // 1. View angle Fresnel glow
    vec3 normal = normalize(vNormal);
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    float fresnel = pow(1.0 - max(0.0, dot(normal, viewDir)), u_fresnelPower);

    // 2. Animated vertical scanlines
    float scanline = sin(vUv.y * 60.0 - u_time * u_scanlineSpeed) * 0.5 + 0.5;

    // 3. Hexagonal energy grid
    float hex = 1.0 - hexPattern(vUv);

    // 4. Energy pulse combination
    float pulse = sin(u_time * 2.0) * 0.2 + 0.8;
    vec3 finalColor = u_shieldColor * (fresnel * 1.5 + hex * 0.8 + scanline * 0.3) * pulse;
    float alpha = clamp(fresnel * 0.8 + hex * 0.6 + scanline * 0.2, 0.1, 0.95);

    gl_FragColor = vec4(finalColor, alpha);
}

precision highp float;

uniform float u_time;
uniform vec3 u_plasmaColor;
uniform float u_plasmaSpeed;
uniform float u_turbulence;

varying vec2 vUv;
varying vec3 vNormal;

// Simplex/Perlin noise helper
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    mat2 rot = mat2(0.8, -0.6, 0.6, 0.8);
    for (int i = 0; i < 4; i++) {
        v += a * noise(p);
        p = rot * p * 2.0 + vec2(100.0);
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 uv = vUv * 4.0;
    float t = u_time * u_plasmaSpeed;

    // Dual-layer domain warping
    vec2 q = vec2(fbm(uv + vec2(0.0, t * 0.2)), fbm(uv + vec2(5.2, 1.3)));
    vec2 r = vec2(fbm(uv + 4.0 * q + vec2(1.7, 9.2) + 0.15 * t), fbm(uv + 4.0 * q + vec2(8.3, 2.8) + 0.126 * t));
    float f = fbm(uv + 4.0 * r * u_turbulence);

    // Color gradient mapping
    vec3 colA = vec3(0.1, 0.0, 0.0);
    vec3 colB = u_plasmaColor;
    vec3 colC = vec3(1.0, 0.95, 0.7);

    vec3 color = mix(colA, colB, clamp(f * f * 4.0, 0.0, 1.0));
    color = mix(color, colC, clamp(length(q) * f, 0.0, 1.0));

    // Corona rim glow
    float rim = 1.0 - max(0.0, dot(normalize(vNormal), vec3(0.0, 0.0, 1.0)));
    color += u_plasmaColor * pow(rim, 3.0) * 2.0;

    gl_FragColor = vec4(color, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec3 u_gridColor;
uniform vec3 u_sunColor;
uniform float u_speed;

varying vec2 vUv;

void main() {
    vec2 uv = (vUv - 0.5) * 2.0;

    // Horizon line
    float horizon = -0.1;
    vec3 finalColor = vec3(0.02, 0.01, 0.06);

    if (uv.y < horizon) {
        // Perspective 3D ground projection
        float depth = 1.0 / (horizon - uv.y);
        vec2 gridUv = vec2(uv.x * depth, depth - u_time * u_speed);

        // Anti-aliased grid lines
        vec2 grid = abs(fract(gridUv - 0.5) - 0.5) / fwidth(gridUv);
        float line = min(grid.x, grid.y);
        float gridIntensity = 1.0 - min(line, 1.0);

        // Exponential fog falloff toward horizon
        float fog = exp(-depth * 0.15);
        finalColor += u_gridColor * gridIntensity * fog;
    } else {
        // Sunset sky gradient
        float sky = (uv.y - horizon) / (1.0 - horizon);
        finalColor = mix(vec3(0.1, 0.0, 0.2), vec3(0.02, 0.0, 0.08), sky);

        // Glowing digital sun with horizontal blinds
        vec2 sunPos = vec2(0.0, 0.25);
        float sunDist = length(uv - sunPos);
        if (sunDist < 0.35) {
            float blinds = sin(uv.y * 50.0) * 0.5 + 0.5;
            float sunCut = smoothstep(0.2, 0.8, blinds);
            float sunGrad = (uv.y - (sunPos.y - 0.35)) / 0.7;
            vec3 sunC = mix(u_sunColor, vec3(1.0, 0.9, 0.2), sunGrad);
            finalColor = mix(finalColor, sunC, sunCut);
        }

        // Sun corona bloom
        finalColor += u_sunColor * (0.15 / (sunDist + 0.1));
    }

    gl_FragColor = vec4(finalColor, 1.0);
}

precision highp float;

uniform float u_time;
uniform float u_iridescence;
uniform float u_roughness;

varying vec2 vUv;
varying vec3 vNormal;

// Spectral rainbow palette generator
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.67);
    return a + b * cos(6.28318 * (c * t + d));
}

void main() {
    vec3 normal = normalize(vNormal);
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    vec3 lightDir = normalize(vec3(1.0, 1.5, 1.0));

    // Specular reflection highlight
    vec3 halfVec = normalize(lightDir + viewDir);
    float NdotH = max(0.0, dot(normal, halfVec));
    float specular = pow(NdotH, mix(128.0, 8.0, u_roughness));

    // View incident angle for thin-film interference
    float NdotV = max(0.0, dot(normal, viewDir));
    float thinFilm = pow(1.0 - NdotV, 2.0) + sin(vUv.x * 10.0 + u_time) * 0.1;
    vec3 rainbow = palette(thinFilm * u_iridescence);

    // Liquid chrome base metal
    vec3 chrome = vec3(0.85, 0.88, 0.92) * (NdotV * 0.4 + 0.6);
    vec3 finalColor = mix(chrome, rainbow, 0.65) + vec3(specular * 1.5);

    gl_FragColor = vec4(finalColor, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec3 u_shallowColor;
uniform vec3 u_deepColor;
uniform float u_causticSpeed;

varying vec2 vUv;

// Voronoi cell distance computation
float voronoi(vec2 p) {
    vec2 n = floor(p);
    vec2 f = fract(p);
    float md = 5.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 g = vec2(float(i), float(j));
            vec2 o = fract(sin(vec2(dot(n + g, vec2(127.1, 311.7)), dot(n + g, vec2(269.5, 183.3)))) * 43758.5453);
            o = 0.5 + 0.5 * sin(u_time * u_causticSpeed + 6.2831 * o);
            vec2 r = g + o - f;
            float d = dot(r, r);
            md = min(md, d);
        }
    }
    return sqrt(md);
}

void main() {
    vec2 uv = vUv * 6.0;

    // Dual-frequency overlapping caustics
    float c1 = voronoi(uv + vec2(u_time * 0.2, 0.0));
    float c2 = voronoi(uv * 1.4 - vec2(0.0, u_time * 0.3));
    float caustic = pow(min(c1, c2), 3.0) * 3.5;

    // Deep water absorption gradient
    float depthGrad = vUv.y;
    vec3 waterColor = mix(u_deepColor, u_shallowColor, depthGrad);
    vec3 finalColor = waterColor + vec3(caustic * 0.8, caustic * 0.9, caustic);

    gl_FragColor = vec4(finalColor, 1.0);
}

precision highp float;

uniform float u_time;
uniform vec3 u_nebulaColorA;
uniform vec3 u_nebulaColorB;
uniform float u_density;

varying vec2 vUv;

float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm(vec2 p) {
    float total = 0.0;
    float amp = 0.5;
    for (int i = 0; i < 5; i++) {
        total += noise(p) * amp;
        p *= 2.1;
        amp *= 0.48;
    }
    return total;
}

void main() {
    vec2 uv = (vUv - 0.5) * 3.0;

    // Drifting nebula dust
    vec2 drift = vec2(u_time * 0.02, u_time * 0.015);
    float n1 = fbm(uv + drift);
    float n2 = fbm(uv * 1.5 - drift + n1 * 1.2);

    vec3 color = mix(u_nebulaColorA * n1, u_nebulaColorB * n2, n2 * u_density);

    // Starfield generation
    vec2 starGrid = fract(uv * 15.0) - 0.5;
    vec2 starId = floor(uv * 15.0);
    float starRand = hash(starId);
    if (starRand > 0.88) {
        float twinkle = sin(u_time * 5.0 + starRand * 100.0) * 0.5 + 0.5;
        float starDist = length(starGrid);
        color += vec3(0.04 / (starDist + 0.05)) * twinkle;
    }

    gl_FragColor = vec4(color, 1.0);
}

#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform float u_time;
uniform vec2 u_resolution;
uniform vec3 u_color;
uniform float u_audio_bass;
uniform float u_audio_mid;
uniform float u_audio_treble;
uniform float u_audio_beat;


// Signed Distance Field Primitives (Inigo Quilez standard formulations)
float sdSphere(vec3 p, float r) {
  return length(p) - r;
}

float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdTorus(vec3 p, vec2 t) {
  vec2 q = vec2(length(p.xz) - t.x, p.y);
  return length(q) - t.y;
}

float sdCylinder(vec3 p, vec2 h) {
  vec2 d = abs(vec2(length(p.xz), p.y)) - h;
  return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

float sdCapsule(vec3 p, vec3 a, vec3 b, float r) {
  vec3 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - r;
}

float sdPlane(vec3 p, vec3 n, float h) {
  return dot(p, normalize(n)) + h;
}


// Signed Distance Field Operators
float opUnion(float d1, float d2) {
  return min(d1, d2);
}

float opSubtraction(float d1, float d2) {
  return max(-d1, d2);
}

float opIntersection(float d1, float d2) {
  return max(d1, d2);
}

float opSmoothUnion(float d1, float d2, float k) {
  float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0.0, 1.0);
  return mix(d2, d1, h) - k * h * (1.0 - h);
}

float opSmoothSubtraction(float d1, float d2, float k) {
  float h = clamp(0.5 - 0.5 * (d2 + d1) / k, 0.0, 1.0);
  return mix(d2, -d1, h) + k * h * (1.0 - h);
}

float opSmoothIntersection(float d1, float d2, float k) {
  float h = clamp(0.5 - 0.5 * (d2 - d1) / k, 0.0, 1.0);
  return mix(d2, d1, h) + k * h * (1.0 - h);
}

vec3 opRepetition(vec3 p, vec3 c) {
  return mod(p + 0.5 * c, c) - 0.5 * c;
}

vec3 opTwist(vec3 p, float k) {
  float c = cos(k * p.y);
  float s = sin(k * p.y);
  mat2 m = mat2(c, -s, s, c);
  return vec3(m * p.xz, p.y).xzy;
}


float map(vec3 p) {
  return opSmoothUnion(sdSphere((p - vec3(-0.6500, 0.0000, 0.0000)), 0.8500), sdSphere((p - vec3(0.6500, 0.0000, 0.0000)), 0.8500), 0.3500);
}

vec3 calcNormal(vec3 p) {
  const float h = 0.0005;
  const vec2 k = vec2(1.0, -1.0);
  return normalize(
    k.xyy * map(p + k.xyy * h) +
    k.yyx * map(p + k.yyx * h) +
    k.yxy * map(p + k.yxy * h) +
    k.xxx * map(p + k.xxx * h)
  );
}

float calcSoftShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
  float res = 1.0;
  float t = mint;
  for (int i = 0; i < 32 && t < maxt; i++) {
    float h = map(ro + rd * t);
    if (h < 0.0010) return 0.0;
    res = min(res, k * h / t);
    t += clamp(h, 0.02, 0.2);
  }
  return clamp(res, 0.0, 1.0);
}

float calcAO(vec3 pos, vec3 nor) {
  float occ = 0.0;
  float sca = 1.0;
  for (int i = 0; i < 5; i++) {
    float h = 0.01 + 0.12 * float(i) / 4.0;
    float d = map(pos + h * nor);
    occ += (h - d) * sca;
    sca *= 0.95;
  }
  return clamp(1.0 - 3.0 * occ, 0.0, 1.0);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution.xy) / min(u_resolution.x, u_resolution.y);

  // Orbit camera around scene
  float camDist = 3.8;
  float camAngle = u_time * 0.4;
  vec3 ro = vec3(camDist * sin(camAngle), 1.8, camDist * cos(camAngle));
  vec3 ta = vec3(0.0, 0.0, 0.0);
  vec3 ww = normalize(ta - ro);
  vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
  vec3 vv = cross(uu, ww);
  vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.6 * ww);

  // Raymarching
  float t = 0.01;
  float d = 0.0;
  bool hit = false;
  for (int i = 0; i < 128; i++) {
    vec3 p = ro + rd * t;
    d = map(p);
    if (d < 0.0010) {
      hit = true;
      break;
    }
    if (t > 40.0) break;
    t += d;
  }

  // Shading
  vec3 col = vec3(0.06, 0.07, 0.1); // Deep background
  if (hit) {
    vec3 pos = ro + rd * t;
    vec3 nor = calcNormal(pos);
    vec3 ref = reflect(rd, nor);

    vec3 lightDir = normalize(vec3(0.8, 1.2, 0.9));
    float diff = max(dot(nor, lightDir), 0.0);
    float spec = pow(max(dot(ref, lightDir), 0.0), 32.0);
    float fre = clamp(1.0 + dot(rd, nor), 0.0, 1.0);
    float shadow = calcSoftShadow(pos + nor * 0.01, lightDir, 0.02, 10.0, 16.0);
    float ao = calcAO(pos, nor);

    vec3 baseCol = (length(u_color) > 0.01) ? u_color : vec3(0.200, 0.700, 1.000);
    vec3 ambient = vec3(0.08, 0.10, 0.14) * ao;
    vec3 diffuse = baseCol * diff * shadow;
    vec3 specular = vec3(1.0, 0.95, 0.9) * spec * shadow;
    vec3 rim = vec3(0.4, 0.7, 1.0) * pow(fre, 3.0) * ao;

    col = ambient + diffuse + specular + rim;
  }

  // Gamma correction
  col = pow(col, vec3(0.4545));
  fragColor = vec4(col, 1.0);
}

